def isLeapYear(year):
    if year % 4 == 0 and year % 100 != 0:
        return 1
    elif year % 400 == 0:
        return 1
    else:
        return 0

def daysInMonth(month, year):
    if month == 2:
        if isLeapYear(year) == 1:
            return 29
        else:
            return 28
    elif month in [1, 3, 5, 7, 8, 10, 12]:
        return 31
    elif month in [4, 6, 9, 11]:
        return 30

month, year = map(int, input().split())
print(daysInMonth(month, year))
